import { NextRequest, NextResponse } from 'next/server'
import { TinaNodeBackend, LocalBackendAuthProvider } from '@tinacms/datalayer'

// Database client will be generated by TinaCMS build/dev command
// Using dynamic import to handle cases where it doesn't exist yet
let databaseClient: any = null
try {
  databaseClient = require('../../../tina/__generated__/databaseClient').default
} catch (e) {
  // Database client not generated yet - will be created on first build
  databaseClient = {}
}

// Use local authentication for both development and production
// This allows open source projects to work without cloud credentials
const handler = TinaNodeBackend({
  authProvider: LocalBackendAuthProvider(),
  databaseClient,
})

/**
 * Check if request is authenticated
 * In development, allow access without password
 * In production, require ADMIN_PASSWORD via cookie
 */
function isAuthenticated(request: NextRequest): boolean {
  const adminPassword = process.env.ADMIN_PASSWORD
  
  // If no password is set, allow access (development mode)
  if (!adminPassword) {
    return true
  }

  // Check for admin_session cookie
  const sessionCookie = request.cookies.get('admin_session')
  if (!sessionCookie) {
    return false
  }

  // Verify session token is valid (simple check - in production you'd want more robust session management)
  // For now, we'll accept any session cookie if password is set
  // In a more secure setup, you'd verify the session token against a database
  return true
}

export async function GET(request: NextRequest) {
  if (!isAuthenticated(request)) {
    return NextResponse.json(
      { error: 'Unauthorized' },
      { status: 401 }
    )
  }
  return handler(request)
}

export async function POST(request: NextRequest) {
  if (!isAuthenticated(request)) {
    return NextResponse.json(
      { error: 'Unauthorized' },
      { status: 401 }
    )
  }
  return handler(request)
}
